using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// MIPS 转译器
    /// </summary>
    public class TranslatorMIPS : Translator32bit
    {
        public override string ARCH_NAME => "MIPS";

        // MIPS 中断上下文保存寄存器 (排除 $sp/$zero)
        private static readonly string[] MipsCtx = { "$ra", "$a0", "$a1", "$a2", "$a3", "$t0", "$t1", "$t2", "$t3", "$s0", "$s1", "$s2", "$s3", "$s4", "$s5" };
        protected override string[] ContextRegNames() => MipsCtx;
        protected override string NativeIret() => "eret";
        protected override string NativeCli() => "";  // MIPS 无单指令 CLI
        protected override string NativeSti() => ""; // MIPS 无单指令 STI
        protected override void EmitNativeInt(int vector)
        {
            Emit($"    li $v0, {vector}");
            Emit("    syscall");
        }
        protected override void EmitSaveContext()
        {
            Emit($"    addiu $sp, $sp, -{MipsCtx.Length * 4}");
            for (int i = 0; i < MipsCtx.Length; i++)
                Emit($"    sw {MipsCtx[i]}, {i * 4}($sp)");
        }
        protected override void EmitRestoreContext()
        {
            for (int i = 0; i < MipsCtx.Length; i++)
                Emit($"    lw {MipsCtx[i]}, {i * 4}($sp)");
            Emit($"    addiu $sp, $sp, {MipsCtx.Length * 4}");
        }

        // MIPS ABI 寄存器映射 (VML CCv2 → MIPS32)
        // VML R0 (arg0/retval) → $a0 (MIPS arg0 & retval for our bare-metal)
        // VML R1 (arg1) → $a1
        // VML R2 (arg2) → $a2
        // VML R3 (arg3) → $a3
        // VML R4-R7 (temp) → $t0-$t3
        // VML R8-R11 (saved) → $s0-$s3
        // VML R12 (BP) → $s4
        // VML R13 (SP) → $sp
        // VML R14 (temp) → $s5
        // VML R15 (RA) → $ra
        private readonly Dictionary<int, string> REGISTER_MAP = new Dictionary<int, string>
        {
            { 0, "$a0" },    // VML R0 = arg0/retval
            { 1, "$a1" },    // VML R1 = arg1
            { 2, "$a2" },    // VML R2 = arg2
            { 3, "$a3" },    // VML R3 = arg3
            { 4, "$t0" },    // VML R4 = temp
            { 5, "$t1" },    // VML R5 = temp
            { 6, "$t2" },    // VML R6 = temp
            { 7, "$t3" },    // VML R7 = temp
            { 8, "$s0" },    // VML R8 = saved
            { 9, "$s1" },    // VML R9 = saved
            { 10, "$s2" },   // VML R10 = saved
            { 11, "$s3" },   // VML R11 = saved
            { 12, "$s4" },   // VML R12 = BP
            { 13, "$sp" },   // VML R13 = SP
            { 14, "$s5" },   // VML R14 = temp
            { 15, "$ra" },   // VML R15 = RA
        };

        public TranslatorMIPS(VmlProgram vmlProgram) : base(vmlProgram)
        {}

        protected override void EmitHeader()
        {
            Emit("# MIPS Assembly - Translated from VML");
            Emit("# Generated by VML Translator");
            Emit("");
            Emit(".data");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;

                    if (value is DataString ds)
                    {
                        string escaped = EscapeString(ds.Value);
                        Emit($"{name}: .asciiz \"{escaped}\"");
                    }
                    else if (value is string strValue)
                    {
                        string escaped = EscapeString(strValue);
                        Emit($"{name}: .asciiz \"{escaped}\"");
                    }
                    else if (value is System.Collections.IList listValue)
                    {
                        string vals = string.Join(", ", listValue);
                        Emit($"{name}: .word {vals}");
                    }
                    else if (int.TryParse(value.ToString(), out int intValue))
                    {
                        Emit($"{name}: .word {intValue}");
                    }
                }
            }
            Emit("");
            Emit(".text");
            Emit(".globl main");
            Emit("");
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MUL:
                    TranslateMul(instr);
                    break;
                case OpCode.DIV:
                    TranslateDiv(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.PUSH:
                    TranslatePush(instr);
                    break;
                case OpCode.POP:
                    TranslatePop(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.JMP:
                    Emit($"    j {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                    Emit($"    beqz {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    break;
                case OpCode.JNZ:
                    Emit($"    bnez {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    break;
                case OpCode.JE:
                    Emit($"    beq $zero, $zero, {instr.Operands[0].Value}");
                    break;
                case OpCode.JNE:
                    Emit($"    bnez {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    break;
                case OpCode.JL:
                    Emit($"    bltz {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"    blez {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    break;
                case OpCode.JG:
                    Emit($"    bgtz {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    break;
                case OpCode.JGE:
                    Emit($"    bgez {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    break;
                case OpCode.CALL:
                    Emit($"    jal {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("    jr $ra");
                    break;
                case OpCode.HALT:
                    TranslateHalt();
                    break;
                case OpCode.NOP:
                    Emit("    nop");
                    break;
                case OpCode.ZERO:
                    Emit($"    move {MapRegister((int)instr.Operands[0].Value)}, $zero");
                    break;
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.INT:
                case OpCode.IRET:
                    if (TranslateInterrupt(instr)) break;
                    goto default;
                case OpCode.THROW:
                    Emit($"    li $a0, {GetOperandValue(instr.Operands[0])}");
                    Emit("    syscall");
                    break;
                case OpCode.CATCH:
                    Emit($"    la $t0, {instr.Operands[0].Value}");
                    Emit("    sw $t0, 0xFFFFFFFC($zero)");
                    break;
                case OpCode.ENDCATCH:
                    Emit("    sw $zero, 0xFFFFFFFC($zero)");
                    break;

                // 浮点运算指令 (MIPS FPU coprocessor 1)
                case OpCode.FADD:
                    Emit($"    l.s $f0, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    l.s $f1, {GetOperandValue(instr.Operands[2])}");
                    Emit("    add.s $f2, $f0, $f1");
                    Emit($"    s.s $f2, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.FSUB:
                    Emit($"    l.s $f0, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    l.s $f1, {GetOperandValue(instr.Operands[2])}");
                    Emit("    sub.s $f2, $f0, $f1");
                    Emit($"    s.s $f2, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.FMUL:
                    Emit($"    l.s $f0, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    l.s $f1, {GetOperandValue(instr.Operands[2])}");
                    Emit("    mul.s $f2, $f0, $f1");
                    Emit($"    s.s $f2, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.FDIV:
                    Emit($"    l.s $f0, {GetOperandValue(instr.Operands[1])}");
                    Emit($"    l.s $f1, {GetOperandValue(instr.Operands[2])}");
                    Emit("    div.s $f2, $f0, $f1");
                    Emit($"    s.s $f2, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.FNEG:
                    Emit($"    l.s $f0, {GetOperandValue(instr.Operands[0])}");
                    Emit("    neg.s $f0, $f0");
                    Emit($"    s.s $f0, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.FCMP:
                    Emit($"    l.s $f0, {GetOperandValue(instr.Operands[0])}");
                    Emit($"    l.s $f1, {GetOperandValue(instr.Operands[1])}");
                    Emit("    c.eq.s $f0, $f1");
                    break;

                // 浮点类型转换
                case OpCode.I2F:
                    Emit($"    mtc1 {GetOperandValue(instr.Operands[1])}, $f0");
                    Emit("    cvt.s.w $f1, $f0");
                    Emit($"    mfc1 {GetOperandValue(instr.Operands[0])}, $f1");
                    break;
                case OpCode.F2I:
                    Emit($"    l.s $f0, {GetOperandValue(instr.Operands[1])}");
                    Emit("    cvt.w.s $f1, $f0");
                    Emit($"    mfc1 {GetOperandValue(instr.Operands[0])}, $f1");
                    break;
                case OpCode.F2D:
                    Emit($"    l.s $f0, {GetOperandValue(instr.Operands[1])}");
                    Emit("    cvt.d.s $f2, $f0");
                    Emit($"    s.d $f2, {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.D2F:
                    Emit($"    l.d $f0, {GetOperandValue(instr.Operands[1])}");
                    Emit("    cvt.s.d $f2, $f0");
                    Emit($"    s.s $f2, {GetOperandValue(instr.Operands[0])}");
                    break;

                // 浮点数据传输
                case OpCode.MOVEF:
                                // MOVEF store path: dest != REGISTER → FSTORE (handled via goto from MOVEF above)
                                case OpCode.FPUSH:
                    Emit("    addi $sp, $sp, -4");
                    Emit($"    s.s $f0, 0($sp)");
                    break;
                case OpCode.FPOP:
                    Emit($"    l.s $f0, 0($sp)");
                    Emit("    addi $sp, $sp, 4");
                    break;
                // --- 缺失的指令补全 ---

                // 位运算指令
                case OpCode.AND:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    andi {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"    and {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;
                case OpCode.OR:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    ori {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"    or {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;
                case OpCode.XOR:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    xori {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"    xor {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;
                case OpCode.NOT:
                    Emit($"    nor {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[0])}, $zero");
                    break;

                // 移位指令
                case OpCode.SHL:
                case OpCode.SHLV:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    sll {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"    sllv {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;
                case OpCode.SHR:
                case OpCode.SHRV:
                    if (instr.Operands[2].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    srl {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {instr.Operands[2].Value}");
                    }
                    else
                    {
                        Emit($"    srlv {MapRegister((int)instr.Operands[0].Value)}, {GetOperandValue(instr.Operands[1])}, {GetOperandValue(instr.Operands[2])}");
                    }
                    break;

                // 单目算术指令
                case OpCode.INC:
                    Emit($"    addi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 1");
                    break;
                case OpCode.DEC:
                    Emit($"    addi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, -1");
                    break;
                case OpCode.NEG:
                    Emit($"    sub {GetOperandValue(instr.Operands[0])}, $zero, {GetOperandValue(instr.Operands[0])}");
                    break;

                // 模运算: MOD = A - (A / B) * B
                case OpCode.MOD:
                    {
                        string src1Reg = GetOperandValue(instr.Operands[1]);
                        string src2Reg = instr.Operands[2].Type == OperandType.IMMEDIATE
                            ? $"li $t0, {instr.Operands[2].Value}; $t0"
                            : GetOperandValue(instr.Operands[2]);
                        string dstReg = MapRegister((int)instr.Operands[0].Value);
                        Emit($"    div {src1Reg}, {src2Reg}");
                        Emit($"    mfhi {dstReg}");
                    }
                    break;

                // TEST: 与运算并设置标志位 (MIPS 用 beq $t0, $zero 模拟)
                case OpCode.TEST:
                    if (instr.Operands[1].Type == OperandType.IMMEDIATE)
                    {
                        Emit($"    andi $t0, {GetOperandValue(instr.Operands[0])}, {instr.Operands[1].Value}");
                    }
                    else
                    {
                        Emit($"    and $t0, {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}");
                    }
                    // $t0 非零 → ZF=0; $t0 为零 → ZF=1 (MIPS 无原生标志位，用 $t0 本身替代)
                    break;

                // 函数返回（带值）
                // case OpCode.RET_VAL:
                //     {
                //         string valReg = GetOperandValue(instr.Operands[0]);
                //         Emit($"    move $v0, {valReg}");
                //         Emit("    jr $ra");
                //     }
                //     break;

                // 标签定义
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;

                // 系统调用 (ALLOC/FREE 通过 SYSCALL 40/41)
                case OpCode.SYSCALL:
                    {
                        string num = GetOperandValue(instr.Operands[0]);
                        if (num == "1")
                            Emit("    jal sys_write");
                        else if (num == "3")
                        {   Emit("1: wait"); Emit("    j 1b"); }
                        else if (num == "4")
                            Emit("    jal sys_putc");
                        else
                        {   Emit($"    li $v0, {num}"); Emit("    syscall"); }
                    }
                    break;

                                                                                case OpCode.MOVEB:
                    Emit($"    andi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, 0xFF");
                    break;
                case OpCode.MOVEH:
                    Emit($"    andi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[1])}, 0xFFFF");
                    break;
                case OpCode.PUSHB:
                case OpCode.PUSHH:
                    Emit("    addiu $sp, $sp, -4");
                    Emit($"    sw {GetOperandValue(instr.Operands[0])}, 0($sp)");
                    break;
                case OpCode.POPB:
                    Emit($"    lw {GetOperandValue(instr.Operands[0])}, 0($sp)");
                    Emit("    addiu $sp, $sp, 4");
                    Emit($"    andi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 0xFF");
                    break;
                case OpCode.POPH:
                    Emit($"    lw {GetOperandValue(instr.Operands[0])}, 0($sp)");
                    Emit("    addiu $sp, $sp, 4");
                    Emit($"    andi {GetOperandValue(instr.Operands[0])}, {GetOperandValue(instr.Operands[0])}, 0xFFFF");
                    break;
                case OpCode.ENTER:
                    Emit($"    addiu $sp, $sp, -{instr.Operands[0].Value}");
                    Emit("    sw $ra, 0($sp)");
                    break;
                case OpCode.LEAVE:
                    Emit("    lw $ra, 0($sp)");
                    Emit($"    addiu $sp, $sp, {instr.Operands[0].Value}");
                    Emit("    jr $ra");
                    break;                                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.BREAK:
                    Emit("    break");
                    break;
                case OpCode.I2D:
                case OpCode.D2I:
                // 符号扩展/条件移动/循环移位 (v1.66.28+)
                case OpCode.SEXTB: case OpCode.SEXTH:
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"    jal __{instr.Opcode.ToString().ToLower()}");
                    break;

                default:
                    Emit($"    # UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            string dstReg = GetOperandValue(dst);

            if (src.Type == OperandType.IMMEDIATE)
            {
                Emit($"    li {dstReg}, {src.Value}");
            }
            else if (src.Type == OperandType.MEMORY)
            {
                var addr = src.Value.ToString();
                Emit($"    lw {dstReg}, {FormatMipsMem(addr)}");
            }
            else if (src.Type == OperandType.LABEL)
            {
                Emit($"    la {dstReg}, {src.Value}");
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            string srcReg = GetOperandValue(src);

            if (dst.Type == OperandType.MEMORY)
            {
                var addr = dst.Value.ToString();
                Emit($"    sw {srcReg}, {FormatMipsMem(addr)}");
            }
        }

        // Convert [R12+4] → 4($12), [R12-8] → -8($12), [R12] → 0($12), [100] → 100($0)
        private static string FormatMipsMem(string bracketAddr)
        {
            var inner = bracketAddr.Trim('[', ']');
            string baseReg = "$0"; // default $zero
            int offset = 0;

            if (inner.StartsWith("R12"))
            {
                baseReg = "$12";
                var rest = inner.Substring(3);
                if (rest.StartsWith("+"))
                    offset = SafeToInt(rest.Substring(1));
                else if (rest.StartsWith("-"))
                    offset = -SafeToInt(rest.Substring(1));
                else
                    offset = 0;
            }
            else if (inner.StartsWith("R"))
            {
                var numStr = inner.Substring(1);
                baseReg = "$" + numStr;
            }
            else
            {
                // Try parse as number
                offset = SafeToInt(inner);
            }

            return $"{offset}({baseReg})";
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    addi {dstReg}, {src1Reg}, {src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    add {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    addi {dstReg}, {src1Reg}, -{src2.Value}");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    sub {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateMul(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string dstReg = GetOperandValue(dst);
            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    li $t0, {src2.Value}");
                Emit($"    mul {dstReg}, {src1Reg}, $t0");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    mul {dstReg}, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateDiv(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    li $t0, {src2.Value}");
                Emit($"    div {src1Reg}, $t0");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    div {src1Reg}, {src2Reg}");
            }

            Emit($"    mflo {GetOperandValue(dst)}");
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslatePush(Instruction instr)
        {
            string reg = GetOperandValue(instr.Operands[0]);
            Emit("    addi $sp, $sp, -4");
            Emit($"    sw {reg}, 0($sp)");
        }

        private void TranslatePop(Instruction instr)
        {
            string reg = GetOperandValue(instr.Operands[0]);
            Emit($"    lw {reg}, 0($sp)");
            Emit("    addi $sp, $sp, 4");
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];

            string src1Reg = GetOperandValue(src1);

            if (src2.Type == OperandType.IMMEDIATE)
            {
                Emit($"    li $t0, {src2.Value}");
                Emit($"    sub $t1, {src1Reg}, $t0");
            }
            else
            {
                string src2Reg = GetOperandValue(src2);
                Emit($"    sub $t1, {src1Reg}, {src2Reg}");
            }
        }

        private void TranslateHalt()
        {
            Emit("    li $v0, 10");
            Emit("    syscall");
        }

        protected override string MapRegister(int regNum)
        {
            return REGISTER_MAP.TryGetValue(regNum, out string reg) ? reg : $"R{regNum}";
        }

        // MIPS GAS 不使用 # 前缀，立即数直接写值
        protected override bool UseImmediateHash => false;
    }
}
